import { setTimeout as sleep } from 'node:timers/promises';
import { immediate, nowIso, openDatabase, type JobRow } from './db.ts';

const db = openDatabase();

const MAX_ATTEMPTS = 3;
const STEP_MS = 100;
const IDLE_POLL_MS = 200;
const HEARTBEAT_MS = 500;
const RETRY_DELAY_MS = 500;
/** Upper bound on shutdown: a single step is at most STEP_MS, so this is only a safety net. */
const FORCE_EXIT_MS = 4000;

let stopping = false;

function writeHeartbeat(): void {
  db.prepare('INSERT INTO heartbeat (id, at) VALUES (1, ?) ON CONFLICT(id) DO UPDATE SET at = excluded.at').run(Date.now());
}

/** Puts a running job back in the queue as if the interrupted attempt had never started. */
function releaseJob(id: string): void {
  db.prepare(
    `UPDATE jobs SET status = 'queued', attempts = MAX(attempts - 1, 0), progress = 0, next_run_at = 0, updated_at = ?
     WHERE id = ? AND status = 'running'`,
  ).run(nowIso(), id);
}

/** Atomically takes the oldest eligible queued job and marks it running for a new attempt. */
function claimNext(): JobRow | undefined {
  return immediate(db, () => {
    const row = db
      .prepare(`SELECT * FROM jobs WHERE status = 'queued' AND next_run_at <= ? ORDER BY seq LIMIT 1`)
      .get(Date.now()) as unknown as JobRow | undefined;
    if (!row) return undefined;
    const now = nowIso();
    db.prepare(`UPDATE jobs SET status = 'running', attempts = attempts + 1, progress = 0, updated_at = ? WHERE id = ?`).run(now, row.id);
    return { ...row, status: 'running', attempts: row.attempts + 1, progress: 0, updated_at: now };
  });
}

/** Runs one attempt of a claimed job. Never holds a transaction open across an await. */
async function processAttempt(job: JobRow): Promise<void> {
  const n = job.attempts;

  if (n <= job.fail_attempts) {
    // Simulated transient failure at the first step, before any progress.
    await sleep(STEP_MS);
    if (stopping) return releaseJob(job.id);
    if (n >= MAX_ATTEMPTS) {
      db.prepare(
        `UPDATE jobs SET status = 'failed', error = 'transient failure', result_output = NULL, progress = 0, updated_at = ?
         WHERE id = ? AND status = 'running'`,
      ).run(nowIso(), job.id);
    } else {
      db.prepare(
        `UPDATE jobs SET status = 'queued', progress = 0, next_run_at = ?, updated_at = ?
         WHERE id = ? AND status = 'running'`,
      ).run(Date.now() + RETRY_DELAY_MS, nowIso(), job.id);
    }
    return;
  }

  for (let i = 1; i <= job.steps; i++) {
    await sleep(STEP_MS);
    if (stopping) return releaseJob(job.id);
    const res = db
      .prepare(`UPDATE jobs SET progress = ?, updated_at = ? WHERE id = ? AND status = 'running'`)
      .run(i, nowIso(), job.id);
    if (res.changes === 0) return; // no longer ours to run
  }

  db.prepare(
    `UPDATE jobs SET status = 'completed', result_output = ?, progress = ?, error = NULL, updated_at = ?
     WHERE id = ? AND status = 'running'`,
  ).run(job.input.toUpperCase(), job.steps, nowIso(), job.id);
}

// Startup: heartbeat first so the server can see the worker, then recover interrupted jobs.
writeHeartbeat();
const heartbeatTimer = setInterval(writeHeartbeat, HEARTBEAT_MS);

const recovered = db
  .prepare(
    `UPDATE jobs SET status = 'queued', attempts = MAX(attempts - 1, 0), progress = 0, next_run_at = 0, updated_at = ?
     WHERE status = 'running'`,
  )
  .run(nowIso());
if (Number(recovered.changes) > 0) console.log(`recovered ${recovered.changes} interrupted job(s)`);
console.log('worker started');

function requestStop(): void {
  if (stopping) return;
  stopping = true;
  // Safety net in case the loop is stuck. Unref'd so it never keeps the process alive by itself.
  setTimeout(() => shutdownNow(), FORCE_EXIT_MS).unref();
}

let exiting = false;
function shutdownNow(): void {
  if (exiting) return;
  exiting = true;
  clearInterval(heartbeatTimer);
  try {
    db.prepare('DELETE FROM heartbeat WHERE id = 1').run();
  } catch {
    // the database may already be unusable; the heartbeat then simply goes stale
  }
  db.close();
  process.exit(0);
}

process.on('SIGTERM', requestStop);
process.on('SIGINT', requestStop);

while (!stopping) {
  let job: JobRow | undefined;
  try {
    job = claimNext();
  } catch (e) {
    console.error('claim failed:', e);
  }
  if (!job) {
    await sleep(IDLE_POLL_MS);
    continue;
  }
  try {
    await processAttempt(job);
  } catch (e) {
    console.error(`attempt for job ${job.id} failed:`, e);
    try {
      releaseJob(job.id);
    } catch {
      // leave it running; startup recovery will pick it up
    }
  }
}

shutdownNow();

